<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> controller.ez5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --language=easy5</span></span>
